<div class="card"><div class="card-header"><div class="topbar u-w-full"><div><h2>Metode Pembayaran</h2><div class="small">Ditampilkan di aplikasi pelanggan.</div></div><div class="u-spacer-260"></div><a class="btn btn-red" href="<?= base_url('payment-methods/create') ?>">+ Tambah</a></div></div><div class="card-body"><?php if(!$rows):?><div class="small">Belum ada metode pembayaran.</div><?php endif;?><table class="table"><thead><tr><th>Metode</th><th>Nomor</th><th>Pemilik</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= html_escape($r->name) ?></td><td><?= html_escape($r->account_number) ?></td><td><?= html_escape($r->account_holder) ?></td><td><span class="badge"><?= $r->is_active?'Aktif':'Nonaktif' ?></span></td><td><a class="btn btn-gold" href="<?= base_url('payment-methods/edit/'.$r->id) ?>">Edit</a></td></tr><?php endforeach;?></tbody></table></div></div>